const base=(document.querySelector('meta[name="app-base"]')?.content||'/').replace(/\/$/,'');
const url=p=>`${base}/${p.replace(/^\//,'')}`;
class ControlChannel{
  constructor(id,onStatus,onRtt){this.clientId=id;this.onStatus=onStatus;this.onRtt=onRtt;this.seq=0;this.pings=new Map();this.stopped=false}
  connect(){this.stopped=false;const p=location.protocol==='https:'?'wss:':'ws:';this.ws=new WebSocket(`${p}//${location.host}${url('ws/control')}?client_id=${encodeURIComponent(this.clientId)}`);this.ws.onopen=()=>this.onStatus(true);this.ws.onclose=()=>{this.onStatus(false,'控制通道已断开');if(!this.stopped)setTimeout(()=>this.connect(),2000)};this.ws.onerror=()=>this.onStatus(false,'控制通道错误');this.ws.onmessage=e=>{const m=JSON.parse(String(e.data));if(m.message==='pong'&&m.seq!==undefined){const t=this.pings.get(m.seq);if(t!==undefined){this.onRtt(Math.round(performance.now()-t));this.pings.delete(m.seq)}}}}
  send(type,payload={}){const seq=++this.seq;if(this.ws?.readyState===WebSocket.OPEN)this.ws.send(JSON.stringify({type,seq,payload}));return seq}
  ping(){const seq=this.send('ping');this.pings.set(seq,performance.now())}
  async acquire(){return (await fetch(`${url('api/session/acquire')}?client_id=${encodeURIComponent(this.clientId)}`,{method:'POST'})).ok}
  async release(){this.send('release_all');await fetch(`${url('api/session/release')}?client_id=${encodeURIComponent(this.clientId)}`,{method:'POST'})}
}
class WhepPlayer{
  constructor(video,endpoint,onState){this.video=video;this.endpoint=endpoint;this.onState=onState;this.stopped=false}
  async start(){this.stopped=false;await this.connect(false)}async restart(){await this.cleanup();this.stopped=false;await this.connect(true)}
  async connect(re){this.onState(re?'reconnecting':'connecting');const pc=new RTCPeerConnection({bundlePolicy:'max-bundle'});this.pc=pc;pc.addTransceiver('video',{direction:'recvonly'});pc.ontrack=e=>{this.video.srcObject=e.streams[0]||new MediaStream([e.track]);this.video.play();this.onState('playing')};pc.onconnectionstatechange=()=>{if(['failed','disconnected'].includes(pc.connectionState)&&!this.stopped)this.reconnect(`WebRTC ${pc.connectionState}`)};try{const o=await pc.createOffer();await pc.setLocalDescription(o);await new Promise(resolve=>{if(pc.iceGatheringState==='complete')return resolve();const timer=setTimeout(resolve,1500);pc.addEventListener('icegatheringstatechange',function f(){if(pc.iceGatheringState==='complete'){clearTimeout(timer);pc.removeEventListener('icegatheringstatechange',f);resolve()}})});const r=await fetch(this.endpoint,{method:'POST',headers:{'Content-Type':'application/sdp'},body:pc.localDescription?.sdp});if(!r.ok)throw new Error(`WHEP returned ${r.status}`);const loc=r.headers.get('Location');if(loc)this.resourceUrl=new URL(loc,location.href).toString();await pc.setRemoteDescription({type:'answer',sdp:await r.text()})}catch(e){await this.cleanup();this.reconnect(String(e))}}
  reconnect(detail){if(this.stopped||this.timer)return;this.onState('failed',detail);this.timer=setTimeout(()=>{this.timer=undefined;this.restart()},3000)}
  async cleanup(){if(this.resourceUrl){fetch(this.resourceUrl,{method:'DELETE'}).catch(()=>{});this.resourceUrl=undefined}this.pc?.close();this.pc=undefined;this.video.srcObject=null}
}
const app=document.querySelector('#app');app.innerHTML=`<header><div><p class="eyebrow">自主研发 · 局域网 IP-KVM</p><h1>LiveKVM 控制台</h1></div><div id="clock"></div></header><main><section class="viewer-card"><div class="viewer-toolbar"><div class="status-row"><span id="video-status" class="pill warn">视频连接中</span><span id="hid-status" class="pill">HID检测中</span><span id="control-status" class="pill">只读</span></div><div class="toolbar-actions"><select id="mouse-mode"><option value="absolute">绝对鼠标</option><option value="relative">相对鼠标</option></select><button id="reconnect">重连视频</button><button id="fullscreen">全屏</button></div></div><div id="stage" class="stage" tabindex="0"><video id="video" autoplay muted playsinline></video><div id="overlay" class="overlay"><strong>点击画面申请控制权</strong><span>按 Esc 退出控制</span></div></div></section><aside><section class="panel"><h2>连接状态</h2><dl><div><dt>分辨率</dt><dd id="resolution">—</dd></div><div><dt>控制RTT</dt><dd id="rtt">—</dd></div><div><dt>在线浏览器</dt><dd id="viewers">—</dd></div><div><dt>CPU</dt><dd id="cpu">—</dd></div><div><dt>内存</dt><dd id="memory">—</dd></div></dl></section><section class="panel"><h2>控制操作</h2><button id="acquire" class="primary">申请控制权</button><button id="release">释放控制权</button><button id="emergency" class="danger">紧急释放全部按键</button><p id="hint">当前为只读观看模式。</p></section><section class="panel compact"><h2>操作提示</h2><p>点击画面捕获键鼠；按 Esc 或切换窗口自动释放。BIOS中鼠标异常时切换为相对模式。</p></section></aside></main>`;
const el=id=>document.querySelector(`#${id}`),video=el('video'),stage=el('stage'),overlay=el('overlay'),clientId=crypto.randomUUID(),pressed=new Set();let hasControl=false,whep,move,frame=0;
const pill=(id,ok,text)=>{const e=el(id);e.textContent=text;e.className=`pill ${ok?'ok':'warn'}`};
const control=new ControlChannel(clientId,(ok,d)=>pill('hid-status',ok,ok?'控制通道在线':d||'控制通道离线'),r=>el('rtt').textContent=`${r} ms`);control.connect();
const videoState=(s,d)=>{const l={idle:'视频已停止',connecting:'视频连接中',playing:'视频正常',reconnecting:'视频重连中',failed:'视频暂不可用'};pill('video-status',s==='playing',l[s]);el('video-status').title=d||''};
async function refresh(){try{const r=await fetch(url('api/status'));if(!r.ok)throw new Error(String(r.status));const s=await r.json();pill('hid-status',s.hid,s.hid?'HID正常':'HID离线');el('resolution').textContent=`${s.width}×${s.height} / ${s.fps}fps`;el('viewers').textContent=s.viewers;if(!whep){whep=new WhepPlayer(video,s.whep_url,videoState);whep.start()}}catch{pill('hid-status',false,'请先登录PiKVM');el('hint').textContent='请先在PiKVM主页登录，再打开本页面。'}}
async function metrics(){try{const m=await fetch(url('api/metrics')).then(r=>r.json());el('cpu').textContent=`${m.cpu_percent.toFixed(1)}%`;el('memory').textContent=`${(m.memory_used_bytes/1048576).toFixed(0)} / ${(m.memory_total_bytes/1048576).toFixed(0)} MB`}catch{}}
async function acquire(){hasControl=await control.acquire();overlay.classList.toggle('hidden',hasControl);pill('control-status',hasControl,hasControl?'控制中':'控制权被占用');el('hint').textContent=hasControl?'键鼠事件正在发送到被控主机。':'另一位用户正在控制。';if(hasControl)stage.focus()}
async function release(){if(hasControl)await control.release();hasControl=false;pressed.clear();overlay.classList.remove('hidden');pill('control-status',false,'只读');el('hint').textContent='当前为只读观看模式。';if(document.pointerLockElement)document.exitPointerLock()}
stage.onclick=()=>{if(!hasControl)acquire()};el('acquire').onclick=acquire;el('release').onclick=release;el('emergency').onclick=()=>{control.send('release_all');release()};el('reconnect').onclick=()=>whep?.restart();el('fullscreen').onclick=()=>stage.requestFullscreen();
addEventListener('keydown',e=>{if(!hasControl)return;if(e.code==='Escape'){release();return}e.preventDefault();if(!pressed.has(e.code)){pressed.add(e.code);control.send('key',{code:e.code,pressed:true})}});addEventListener('keyup',e=>{if(!hasControl)return;e.preventDefault();pressed.delete(e.code);control.send('key',{code:e.code,pressed:false})});addEventListener('blur',release);
const button=n=>['left','middle','right'][n]||'left',clamp=n=>Math.max(-32768,Math.min(32767,n));stage.oncontextmenu=e=>e.preventDefault();stage.onmousedown=e=>{if(hasControl){e.preventDefault();control.send('mouse_button',{button:button(e.button),pressed:true})}};stage.onmouseup=e=>{if(hasControl)control.send('mouse_button',{button:button(e.button),pressed:false})};stage.addEventListener('wheel',e=>{if(hasControl){e.preventDefault();control.send('wheel',{dy:Math.max(-127,Math.min(127,Math.round(-e.deltaY/4)))})}},{passive:false});stage.onmousemove=e=>{if(!hasControl)return;if(el('mouse-mode').value==='relative'){control.send('mouse_move_rel',{dx:clamp(e.movementX),dy:clamp(e.movementY)});return}const r=video.getBoundingClientRect();move={x:Math.round(Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))*65535-32768),y:Math.round(Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))*65535-32768)};if(!frame)frame=requestAnimationFrame(()=>{frame=0;if(move){control.send('mouse_move_abs',move);move=undefined}})};
setInterval(()=>control.ping(),2000);setInterval(refresh,3000);setInterval(metrics,3000);setInterval(()=>el('clock').textContent=new Date().toLocaleTimeString('zh-CN',{hour12:false}),1000);refresh();metrics();
